p=subprocess.Popen(['/harness-state/.gbrain/gbrain-keyless','serve','--surface','starter','--advertise','verbs'],stdin=subprocess.PIPE,stdout=subprocess.PIPE,stderr=open('/tmp/gbrain-mcp-smoke.stderr','w'),text=True,bufsize=1)
def call(i,method,params):
 p.stdin.write(json.dumps({'jsonrpc':'2.0','id':i,'method':method,'params':params})+'\n');p.stdin.flush()
 end=time.time()+50
 while time.time()<end:
  if select.select([p.stdout],[],[],max(0,end-time.time()))[0]:
   s=p.stdout.readline()
